        // read below is its latest state.
        if (to == ClaimStatus.OPEN) {
            sheets.lock(sheetId);
        }
        Claim claim = claim(sheetId, personId, id);
        settings.refuseUnless(sheetId, user, switch (to) {
            case OPEN -> Permission.OPEN;
            case SETTLED -> Permission.SETTLE;
